"""Builds Italian XBRL instances shaped like the ones generated by the InfoCamere tools
(taxonomy itcc-ci 2018-11-04), for tests. Company and figures are fictitious."""

NS_ITCC = "http://www.infocamere.it/itnn/fr/itcc/ci/2018-11-04"

CURRENT = {
    "TotaleAttivo": 4_000_000, "TotaleImmobilizzazioni": 1_900_000, "TotaleImmobilizzazioniMateriali": 1_500_000,
    "TotaleAttivoCircolante": 2_050_000, "TotaleRimanenze": 700_000, "AttivoRateiRisconti": 50_000,
    "TotalePatrimonioNetto": 300_000, "PatrimonioNettoCapitale": 500_000, "PatrimonioNettoRiservaLegale": 20_000,
    "PatrimonioNettoUtiliPerditePortatiNuovo": -100_000, "PatrimonioNettoUtilePerditaEsercizio": -120_000,
    "TotaleFondiRischiOneri": 100_000, "TrattamentoFineRapportoLavoroSubordinato": 200_000,
    "TotaleDebiti": 3_300_000, "PassivoRateiRisconti": 100_000,
    "DebitiDebitiTributariTotaleDebitiTributari": 260_000,
    "DebitiDebitiVersoIstitutiPrevidenzaSicurezzaSocialeTotaleDebitiVersoIstitutiPrevidenzaSicurezzaSociale": 90_000,
    "ValoreProduzioneRicaviVenditePrestazioni": 5_000_000, "DifferenzaValoreCostiProduzione": 250_000,
    "CostiProduzioneAmmortamentiSvalutazioniTotaleAmmortamentiSvalutazioni": 180_000,
    "CostiProduzioneAccantonamentiRischi": 10_000, "CostiProduzioneAltriAccantonamenti": 5_000,
    "ProventiOneriFinanziariInteressiAltriOneriFinanziariTotaleInteressiAltriOneriFinanziari": 160_000,
    "UtilePerditaEsercizio": -120_000, "FlussoFinanziarioAttivitaOperativa": 90_000,
}
PREVIOUS = {"TotaleAttivo": 3_800_000, "TotalePatrimonioNetto": 420_000, "UtilePerditaEsercizio": -40_000,
            "ValoreProduzioneRicaviVenditePrestazioni": 5_200_000, "TotaleDebiti": 3_000_000}

# Ordinary scheme: within/beyond split per debt item. Abridged scheme: one aggregate split.
ORDINARY_SPLIT = {
    "DebitiDebitiVersoBancheEsigibiliEntroEsercizioSuccessivo": 900_000,
    "DebitiDebitiVersoBancheEsigibiliOltreEsercizioSuccessivo": 1_000_000,
    "DebitiDebitiVersoFornitoriEsigibiliEntroEsercizioSuccessivo": 1_050_000,
    "DebitiDebitiTributariEsigibiliEntroEsercizioSuccessivo": 260_000,
    "DebitiDebitiVersoIstitutiPrevidenzaSicurezzaSocialeEsigibiliEntroEsercizioSuccessivo": 90_000,
}
ABRIDGED_SPLIT = {"DebitiEsigibiliEntroEsercizioSuccessivo": 2_300_000, "DebitiEsigibiliOltreEsercizioSuccessivo": 1_000_000}

DURATION_ITEMS = {
    "ValoreProduzioneRicaviVenditePrestazioni", "DifferenzaValoreCostiProduzione",
    "CostiProduzioneAmmortamentiSvalutazioniTotaleAmmortamentiSvalutazioni", "CostiProduzioneAccantonamentiRischi",
    "CostiProduzioneAltriAccantonamenti",
    "ProventiOneriFinanziariInteressiAltriOneriFinanziariTotaleInteressiAltriOneriFinanziari",
    "UtilePerditaEsercizio", "FlussoFinanziarioAttivitaOperativa",
}


def _context(cid, year, instant, dim=False):
    period = (f"<instant>{year}-12-31</instant>" if instant
              else f"<startDate>{year}-01-01</startDate><endDate>{year}-12-31</endDate>")
    scenario = ('<xbrldi:explicitMember dimension="itcc-ci:VariazioniPatrimonioNettoAxis">itcc-ci:Esempio'
                '</xbrldi:explicitMember>' if dim else "<itcc-ci:scen>itcc-ci:depositato</itcc-ci:scen>")
    return (f'<context id="{cid}"><entity><identifier scheme="http://www.infocamere.it">01234567890</identifier>'
            f"</entity><period>{period}</period><scenario>{scenario}</scenario></context>")


def _fact(name, ctx, value):
    return f'<itcc-ci:{name} contextRef="{ctx}" unitRef="EUR" decimals="0">{value}</itcc-ci:{name}>'


def build_instance(scheme="abridged", with_split=True, ateco="25.62.00",
                   legal_form="societa' a responsabilita' limitata") -> bytes:
    split = (ABRIDGED_SPLIT if scheme == "abridged" else ORDINARY_SPLIT) if with_split else {}
    schema = "itcc-ci-abb-2018-11-04.xsd" if scheme == "abridged" else "itcc-ci-ese-2018-11-04.xsd"
    parts = [
        '<?xml version="1.0" encoding="UTF-8"?>',
        "<!--XBRLCOMPILER;COMPNAME=INFOCAMERE;TOOL=XBRL_NI_GENERATOR;VER=TAX 20181104-->",
        '<xbrl xmlns="http://www.xbrl.org/2003/instance" xmlns:link="http://www.xbrl.org/2003/linkbase" '
        'xmlns:xlink="http://www.w3.org/1999/xlink" xmlns:iso4217="http://www.xbrl.org/2003/iso4217" '
        'xmlns:xbrli="http://www.xbrl.org/2003/instance" xmlns:xbrldi="http://xbrl.org/2006/xbrldi" '
        'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" '
        f'xmlns:itcc-ci="{NS_ITCC}">',
        f'<link:schemaRef xlink:type="simple" xlink:href="{schema}"/>',
        _context("c2024_i", 2024, True), _context("c2024_d", 2024, False),
        _context("c2023_i", 2023, True), _context("c2023_d", 2023, False),
        _context("c2024_d_dim", 2024, False, dim=True),
        '<unit id="EUR"><measure>iso4217:EUR</measure></unit>',
        '<itcc-ci:DatiAnagraficiDenominazione contextRef="c2024_i">ROSSI MECCANICA S.R.L.</itcc-ci:DatiAnagraficiDenominazione>',
        '<itcc-ci:DatiAnagraficiCodiceFiscale contextRef="c2024_i">01234567890</itcc-ci:DatiAnagraficiCodiceFiscale>',
        f'<itcc-ci:DatiAnagraficiFormaGiuridica contextRef="c2024_i">{legal_form}</itcc-ci:DatiAnagraficiFormaGiuridica>',
    ]
    if ateco:
        parts.append(f'<itcc-ci:DatiAnagraficiSettoreAttivitaPrevalenteAteco contextRef="c2024_i">{ateco}'
                     "</itcc-ci:DatiAnagraficiSettoreAttivitaPrevalenteAteco>")
    for year, values in (("2024", {**CURRENT, **split}), ("2023", PREVIOUS)):
        for name, value in values.items():
            ctx = f"c{year}_d" if name in DURATION_ITEMS else f"c{year}_i"
            parts.append(_fact(name, ctx, value))
    # Distractors: a dimensional fact and a nil fact must be ignored.
    parts.append(_fact("TotaleDebiti", "c2024_d_dim", 999_999_999))
    parts.append('<itcc-ci:CostiProduzioneOneriDiversiGestione contextRef="c2024_d" unitRef="EUR" '
                 'decimals="0" xsi:nil="true"/>')
    parts.append("</xbrl>")
    return "\n".join(parts).encode("utf-8")


def sign_p7m(content: bytes) -> bytes:
    """Wraps the content in a CMS SignedData envelope (no signer, enough to test the unwrapping)."""
    from asn1crypto import cms

    signed = cms.SignedData({
        "version": "v1",
        "digest_algorithms": [],
        "encap_content_info": {"content_type": "data", "content": content},
        "signer_infos": [],
    })
    return cms.ContentInfo({"content_type": "signed_data", "content": signed}).dump()
